INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 11, "", "", 111031, 10, 13020019, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", "", "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 93, "", "", 5, "", 13020020, "", "", "", "");
