INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 3, "", "", 111031, 1, 13020022, "nyx_cmn_03", 0.2, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 11, "", "", 111031, 10, 13020023, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 91, "", "", 0, "", 13020024, "", "", "", "");
