INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 91, "", "", 0, "", 13020027, 1, "", "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 11, "", "", 111031, 10, 13020028, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 91, "", "", 0, "", 13020029, 1, "", "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 3, "", "nyx_302_yuni_04", 111031, 0, 13020030, "nyx_302_yuni_03", 0.2, "", 1);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 11, "", "", 111031, 10, 13020031, "是非もなし\nいざ往かん！", "", "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (302, 91, "", "", 0, "", 13020032, 1, "", "", "");
